{"file_path":"tests/test_metrics.py","content":"from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_every_transcript_once():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_fields_and_ignored_lines():
    assert parse_transcript_log(
        ["  # comment", "", "  x1 , 3 , 1  ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_errors_include_input_line_number():
    for lines, expected_line in [(["# comment", "x,not-a-day,1"], 2), (["x,1,1,extra"], 1)]:
        try:
            parse_transcript_log(lines)
        except ValueError as exc:
            assert f"line {expected_line}" in str(exc)
        else:
            raise AssertionError("expected ValueError")


def test_dedupe_keeps_last_duplicate_and_sorts():
    events = [
        {"id": "b", "day": 3, "flagged": False},
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 1, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 4, "flagged": None},
    ]
    assert daily_flag_counts(events, 2, 4) == [0, 1, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_uses_specified_precision_recent_window_and_nonempty_groups():
    groups = {
        "a": [
            {"id": "1", "day": 1, "flagged": True},
            {"id": "2", "day": 2, "flagged": False},
        ],
        "b": [{"id": "3", "day": 3, "flagged": True}],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_and_group_rates():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "b": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 2) == ["a", "b"]
    assert flag_rate_by_group(groups) == {
        "a": 1.0,
        "b": 1.0,
        "empty": None,
        "z": 0.5,
    }


def test_longest_flag_streak_only_counts_positive_entries():
    assert longest_flag_streak([1, 2, 0, -1, 3, 1]) == 2
    assert longest_flag_streak([]) == 0
